use super::formatting::{clamp_ratio, format_ratio_as_percentage};

#[derive(Clone, Debug, PartialEq)]
pub struct ProgressBar {
    progress: u64,
    total: u64,
    width: usize,
}

impl Default for ProgressBar {
    fn default() -> Self {
        Self::new()
    }
}

impl ProgressBar {
    pub fn new() -> Self {
        Self {
            progress: 0,
            total: 100,
            width: 0,
        }
    }

    pub fn set_progress(&mut self, progress: u64) {
        self.progress = progress;
    }

    pub fn set_total(&mut self, total: u64) {
        self.total = total;
    }

    pub fn set_width(&mut self, width: usize) {
        self.width = width;
    }

    pub fn str(&self) -> String {
        let ratio = clamp_ratio(self.progress, self.total);
        let inside = self.render_inside(ratio);
        let percentage = format_ratio_as_percentage(ratio);
        format!("[{inside}] {percentage}")
    }

    fn render_inside(&self, ratio: f64) -> String {
        if self.width == 0 {
            return String::new();
        }

        if ratio >= 1.0 {
            return "=".repeat(self.width);
        }

        let filled = (self.width as f64 * ratio).floor() as usize;
        let mut inside = String::with_capacity(self.width);
        inside.push_str(&"=".repeat(filled));
        inside.push('>');
        inside.push_str(&" ".repeat(self.width.saturating_sub(filled + 1)));
        inside
    }
}
